mapper.sql:
where e.clan_id=#{criteria.clanId} and e.deleted_at is null
  and e.branch_id in #{id}
  and e.branch_id in #{v}
  and e.founder_person_id=#{criteria.founderPersonId}
  and e.data_status in #{v}
  and e.privacy_level=#{criteria.privacyLevel}
  and lower(coalesce(e.from_location,'')) like concat('%',lower(#{criteria.fromLocation}),'%')
  and lower(coalesce(e.to_location,'')) like concat('%',lower(#{criteria.toLocation}),'%')
  and lower(coalesce(e.migration_time_text,'')) like concat('%',lower(#{criteria.migrationTimeText}),'%')
  and (lower(coalesce(e.from_location,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(e.to_location,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(e.migration_time_text,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(e.reason,'')) like concat('%',lower(#{criteria.keyword}),'%') or lower(coalesce(e.description,'')) like concat('%',lower(#{criteria.keyword}),'%'))
  and ((e.privacy_level not in ('relatives_only','private','sealed') and e.sensitive_level not in ('sensitive','highly_sensitive')) or e.created_by=#{criteria.actorId} or e.branch_id in #{id})
